 JobsSchemaMigration::apply($db,$prefix);$env=['FMONITOR_DB_HOST'=>$host,'FMONITOR_DB_PORT'=>(string)$port,'FMONITOR_DB_NAME'=>$name,'FMONITOR_DB_USER'=>$adminUser,'FMONITOR_DB_PASSWORD'=>$adminPassword,'FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix,'FMONITOR_SESSION_INSTANCE'=>'acceptance'];foreach($env as$k=>$v)putenv($k.'='.$v);$config=JobsRuntimeConfiguration::fromEnvironment();$tokens=[str_repeat('a',64)];$queue=new MariaDbJobQueue($db,$prefix,null,static function()use(&$tokens):string{return array_shift($tokens);},['outbox.dispatch'=>[1]]);$outbox=new MariaDbOutbox($db,$prefix);$db->begin_transaction();$intent=$outbox->append(['eventId'=>'acceptance-event','channel'=>'acceptance','template'=>'deterministic-v1','version'=>1,'data'=>['objectId'=>4512]]);$db->commit();(new OutboxDispatchScheduler($outbox,$queue))->enqueuePending();$lease=$queue->claim(['workerId'=>'worker:acceptance','batch'=>1])[0];$before=(int)$db->query("SELECT COUNT(*) FROM `{$prefix}fm2_job_events`")->fetch_column();$provider='acceptance-'.hash('sha256','acceptance-event');$outcome=FMonitor2\Jobs\JobHandlerRuntime::handle($lease,$config);assertSameValue(['completed','delivered',$provider],[$outcome['status'],$outcome['result']['outcome']??null,$outcome['result']['providerReference']??null],'existing outbox owner maps delivery to worker completed');$attempt=$db->query("SELECT intent_id,job_id,attempt,outcome,provider_reference FROM `{$prefix}fm2_outbox_attempt_events`")->fetch_assoc();assertSameValue([(string)$intent['intentId'],(string)$lease['jobId'],'1','delivered',$provider],array_values($attempt),'domain delivery attempt retained');assertSameValue($outcome,FMonitor2\Jobs\JobHandlerRuntime::handle($lease,$config),'replay deterministic');assertSameValue([1,'delivered',$before],[(int)$db->query("SELECT COUNT(*) FROM `{$prefix}fm2_outbox_attempt_events`")->fetch_column(),$db->query("SELECT status FROM `{$prefix}fm2_outbox_intents`")->fetch_column(),(int)$db->query("SELECT COUNT(*) FROM `{$prefix}f